// Lấy thread_text từ node trước đó
const threadText = $("Prepare Thread Data").first().json.thread_text;

if (!threadText) {
  return [{ threadText: "No content provided" }];
}

// Tách phần hook/intro (trước ---Thread--- đầu tiên)
const parts = threadText.split("---Thread---");
const tweets = [];

// Tweet đầu tiên là hook/intro
if (parts[0]) {
  tweets.push(parts[0].trim());
}

// Xử lý các phần còn lại
for (let i = 1; i < parts.length; i++) {
  const section = parts[i].trim();

  // Tìm và tách theo emoji số (1️⃣, 2️⃣, etc.) hoặc pattern số khác
  const numberPattern = /([1-9]️⃣|[1-9]\.|[1-9]\))/g;
  const points = section.split(numberPattern);

  // Ghép lại số với nội dung tương ứng
  for (let j = 1; j < points.length; j += 2) {
    if (points[j] && points[j + 1]) {
      const number = points[j];
      const content = points[j + 1].trim();
      tweets.push(`${number} ${content}`);
    }
  }

  // Nếu không có số nào, giữ nguyên section
  if (points.length === 1 && section) {
    tweets.push(section);
  }
}

// Return array của tweet objects
return tweets.map(text => ({
  threadText: text.trim()
}));
